/** Generated by the bounded Red Team routing optimizer. */
export const aliases = Object.freeze({
  "orchestrator": "plan_specialists",
  "evaluator": "evaluate",
  "independent-judge": "judge",
  "inventory-scope": "preflight_inventory",
  "identity-posture": "identity",
  "authorization-attack-path": "correlate",
  "network-exposure": "network",
  "compute-platform": "compute",
  "aks-container": "aks-container",
  "data-protection": "data",
  "web-exposure": "web",
  "ai-foundry": "ai",
  "attack-surface": "easm",
  "external-vuln": "external-vuln",
  "logging-coverage": "logging",
  "email-security": "email",
  "governance-posture": "governance",
  "devops-supplychain": "supplychain",
  "reporting": "report"
});
export function resolveNode(nodes, value) {
  if (typeof value !== 'string' || !value.trim()) return null;
  const raw=value.trim(), key=raw.toLowerCase(), normalized=key.replace(/^red team /,'').replaceAll(' ','-');
  return nodes.find(n=>n.id===raw || n.agent===raw || n.domain===raw || n.id===normalized || n.agent?.toLowerCase()===key) || nodes.find(n=>n.id===aliases[key]) || null;
}
